local TrailStageHome = Class("TrailStageHome")

function TrailStageHome:__init()
    self.handler = nil
    self.selectType = TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.START_BUTTON
    self._timer = nil
    self._loader = nil
end

function TrailStageHome:__delete()
    self.selectType = nil
    self._loader = nil
    self.controller = nil
    self.handler = nil
    --self._timer = nil
end

function TrailStageHome:Awake()
    trailBattleMgr = TrailBattleMgr:GetInstance()
    self:SetFunctionButtonActions()
    self.handler = Bind(self, self.OnAngleEventAction)
    Events.AddListener(Constants.EventNames.SCROLL_CHANGE, self.handler)
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if playerComponent then
        local trialRemainTime = checkInt(playerComponent.playerDojo.trialRemainTime)
        self.TimeText.text = string.format('timer %s', CfUtils.GetTimeHumanize(trialRemainTime - Constants.MIN_TRIAL_CAN_ENTER))

        self._timer = CDTimerModule.GetInstance():AddCD(1, function(count, id)
            if count <= 0 then
                self.TimeText.text = localize('结算中')
            else
                self.TimeText.text = string.format('timer %s', CfUtils.GetTimeHumanize(count))
            end
        end, trialRemainTime - Constants.MIN_TRIAL_CAN_ENTER, false, true, true)
    end
end

---SetFunctionButtonActions
---设置功能按钮的事件
function TrailStageHome:SetFunctionButtonActions()
    local function OnTaskButtonAction(eventPoint)
        ---去任务页面
        UIModule.OpenDialog({ id = Constants.UITypeIds.UITrailStageTasks })
    end
    local function OnRankButtonAction(eventData)
        ---去排名页面
        UIModule.OpenDialog({ id = Constants.UITypeIds.UITrailStageRankDialog })
    end
    local function OnStoreButtonAction(eventData)
        ---去商城页面
        ---@type StoreUtils
        local storeUtils = import('Game.UI.Store.StoreUtils')
        local StoreConstants = import('Game.UI.Store.StoreConstants')
        storeUtils.OpenStore(StoreConstants.OpenIds.StoreTrailStage)
    end
    UIEventProxy.Create(self.TaskButton:Find("Button").gameObject).onPointerClick = OnTaskButtonAction
    UIEventProxy.Create(self.TaskButton.gameObject).onPointerClick = OnTaskButtonAction
    UIEventProxy.Create(self.StoreButton:Find("Button").gameObject).onPointerClick = OnStoreButtonAction
    UIEventProxy.Create(self.StoreButton.gameObject).onPointerClick = OnStoreButtonAction
    UIEventProxy.Create(self.RankButton:Find("Button").gameObject).onPointerClick = OnRankButtonAction
    UIEventProxy.Create(self.RankButton.gameObject).onPointerClick = OnRankButtonAction
    UIEventProxy.Create(self.FightButton.gameObject).onPointerClick = function(eventData)
        ---去关卡页面
        UIModule.OpenDialog({ id = Constants.UITypeIds.UITrailStageQuestDialog })
    end
    UIEventProxy.Create(self.LocationButton.gameObject).onPointerClick = function(eventData)
        ---去我当前名次的位置
        ---@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        trailBattleMgr:ScrollToAngleByPlayerId(playerComponent.playerDojo.playerId)
    end
    UIEventProxy.Create(self.TopBg.gameObject).onPointerClick = function(eventData)
        ---去段位奖励
        UIModule.OpenDialog({ id = Constants.UITypeIds.UITrailStageRewardPreview })
    end
end

---FreshStartLevelNode
---@param text string
---@param isActive boolean
---@param isCreate boolean
function TrailStageHome:FreshStartLevelNode(text, isActive, isCreate)
    isActive = checkBool(isActive)
    isCreate = checkBool(isCreate)
    if not isActive then
        KTool.SetActive(self.StartLevelNode.gameObject, false)
        KTool.SetActive(self.TargetLevelNode.gameObject, true)
        return
    end
    if not string.isEmpty(text) then
        self.DescText.text = text
    end
    local PlayerNumTextTrans = self.StartLevelNode.transform:Find("Image/PersonPreviewButton/PlayerNumText")
    if not isNull(PlayerNumTextTrans) then
        local enterData = trailBattleMgr:GetEnterData()
        local roomRank = checkTable(enterData.roomRank)
        local remainCount = 0
        for i, v in pairs(roomRank) do
            if checkInt(v.score) <= 0 then
                remainCount = remainCount + 1
            end
        end
        KTool.GetComponent(PlayerNumTextTrans.gameObject, typeof(Text)).text = tostring(remainCount)
    end
    if isCreate then
        local buttonTrans = self.StartLevelNode.transform:Find("Image/PersonPreviewButton")
        UIEventProxy.Create(buttonTrans.gameObject).onPointerClick = function(eventData)
            ---打开未参加评分的人数
            local enterData = trailBattleMgr:GetEnterData()
            local roomRank = checkTable(enterData.roomRank)
            local remainCount = 0
            for i, v in pairs(roomRank) do
                if checkInt(v.score) <= 0 then
                    remainCount = remainCount + 1
                end
            end
            if remainCount > 0 then
                UIModule.OpenDialog({ id = Constants.UITypeIds.UITrailStagePlayerDialog })
            end
        end
    end
end

---FreshUI
function TrailStageHome:FreshUI(enterData)
    local segmentVo = trailBattleMgr:GetSegmentRewardVoByRefId(enterData.segment)
    self.RankNameText.text = segmentVo.name
    ---@type Engine.UI.ImageAlterable
    local imageAlterable = KTool.GetOrAddComponent(self.RankIcon.gameObject, typeof(ImageAlterable))
    imageAlterable:LoadSprite(trailBattleMgr:GetSegmentIconPath(enterData.segment))
    self.NumText.text = string.format('%d point', checkNumber(enterData.score))
    self:FreshButtonGroup(enterData)
end

---FreshButtonGroup
---@param enterDojo TrailEnterDojo
function TrailStageHome:FreshButtonGroup(enterDojo)
    local GroupMB = GetLuaBehaviour(self.LevelGroupNode.gameObject, TrailButtonGroupNodeLuaPath)
    if GroupMB then
        if isNull(GroupMB.Env) then
            GroupMB:Init()
        end
        ---@type TrailButtonGroupNode
        local env = GroupMB.Env
        env:FreshButtonGroup(enterDojo, Bind(self, self.OnSegmentGroupButtonAction))
    end
end

---OnAngleEventAction
---@param actionType number
function TrailStageHome:OnAngleEventAction(actionType)
    if self.selectType == actionType then
        return
    end
    self.selectType = actionType
    local GroupMB = GetLuaBehaviour(self.LevelGroupNode.gameObject, TrailButtonGroupNodeLuaPath)
    if GroupMB then
        if isNull(GroupMB.Env) then
            GroupMB:Init()
        end
        ---@type TrailButtonGroupNode
        local env = GroupMB.Env
        if env:IsActive(actionType) then
            env:SetCheckIndex(actionType)
            self:FlashShowFlagButton(actionType)
            self:OnExecute(true)
        end
    end
end

---FlashShowFlagButton
---显示一下具体的显示
function TrailStageHome:FlashShowFlagButton(actionType)
    KTool.SetActive(self.CircleFlagButton.gameObject, true)
    ---@type UnityEngine.CanvasGroup
    local canvasGroup = KTool.GetOrAddComponent(self.CircleFlagButton.gameObject, typeof(CS.UnityEngine.CanvasGroup))
    ---@type UnityEngine.UI.Text
    local textMB = KTool.GetComponent(self.CircleFlagButton.transform:Find('Text').gameObject, typeof(Text))
    local _, myRankGroup = trailBattleMgr:GetRankGroupBySegment(trailBattleMgr:GetMySegment())
    KTool.SetActive(self.CurrentFlag.gameObject, myRankGroup == actionType)
    if actionType == TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.UP_BUTTON then
        canvasGroup.alpha = 1
        if textMB then
            textMB.text = localize('晋级组')
        end
        canvasGroup:DOFade(0, 0.5):SetDelay(1)
    elseif actionType == TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.STAY_BUTTON then
        canvasGroup.alpha = 1
        if textMB then
            textMB.text = localize('保级组')
        end
        canvasGroup:DOFade(0, 0.5):SetDelay(1)
    elseif actionType == TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.DOWN_BUTTON then
        canvasGroup.alpha = 1
        if textMB then
            textMB.text = localize('降级组')
        end
        canvasGroup:DOFade(0, 0.5):SetDelay(1)
    end
end

---OnSegmentGroupButtonAction
---不同按钮的响应事件
---@param actionType number
function TrailStageHome:OnSegmentGroupButtonAction(actionType, executeAnimation)
    executeAnimation = checkBool(executeAnimation)
    if self.selectType == actionType then
        return
    end
    local isRight = actionType > self.selectType
    self.selectType = actionType
    self:FlashShowFlagButton(actionType)
    self:OnExecute(executeAnimation, isRight)
end

function TrailStageHome:OnExecute(executeAnimation, isRight)
    KTool.SetActive(self.StartLevelNode.gameObject, self.selectType == TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.START_BUTTON)
    KTool.SetActive(self.TargetLevelNode.gameObject, self.selectType ~= TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.START_BUTTON)
    if self.selectType ~= TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.START_BUTTON then
        ---刷新奖励的信息
        local enterDojo = trailBattleMgr:GetEnterData()
        local mySegment = checkInt(enterDojo.segment)
        ---@type TrailSegmentRewardVo
        local segmentRewards = trailBattleMgr:GetSegmentRewardVoBySegment(mySegment)
        local segmentRewardVo = nil
        if self.selectType == TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.DOWN_BUTTON then
            ---降级的逻辑
            if segmentRewards.downGrade ~= 0 then
                ----存在降级分阶
                segmentRewardVo = segmentRewards.downRewards
                local low, upper = checkInt(segmentRewards.downGrade[1]), checkInt(segmentRewards.downGrade[2])
                if not executeAnimation then
                    trailBattleMgr:ScrollToAngleBySeqNo(low, true, isRight)
                end
                self.SeqText.text = string.format('%02d~%02d', low, upper)
            end

        elseif self.selectType == TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.STAY_BUTTON then
            ---保级
            if segmentRewards.keepGrade ~= 0 then
                ----存在保级分阶
                segmentRewardVo = segmentRewards.keepRewards
                local low, upper = checkInt(segmentRewards.keepGrade[1]), checkInt(segmentRewards.keepGrade[2])
                if not executeAnimation then
                    trailBattleMgr:ScrollToAngleBySeqNo(low, true, isRight)
                end
                self.SeqText.text = string.format('%02d~%02d', low, upper)
            end

        elseif self.selectType == TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.UP_BUTTON then
            ---晋级的逻辑
            local seqNo = 1
            local maxNo = 1
            if segmentRewards.upGrade ~= 0 then
                ----存在晋级分阶
                segmentRewardVo = segmentRewards.upRewards
                seqNo = checkInt(segmentRewards.upGrade[1])
                maxNo = checkInt(segmentRewards.upGrade[2])
            end

            if not executeAnimation then
                trailBattleMgr:ScrollToAngleBySeqNo(seqNo, true, isRight)
            end
            self.SeqText.text = string.format('%02d~%02d', seqNo, maxNo)
        end
        if isTable(segmentRewardVo) then
            KTool.DestroyGameObjectChildren(self.RewardNode.gameObject, true)
            ---建立奖励节点
            for i, v in pairs(segmentRewardVo) do
                local go = KTool.Instantiate(self.RewardNode.gameObject, self.PrefabNode.gameObject, false)
                KTool.SetActive(go, true)
                local goodNodeTrans = go.transform:Find("GoodNode")
                if not isNull(goodNodeTrans) then
                    local goodItemNodeMB = GetLuaBehaviour(goodNodeTrans.gameObject, GoodsNodePath)
                    if not isNull(goodItemNodeMB) then
                        if isNull(goodItemNodeMB.Env) then
                            goodItemNodeMB:Init()
                        end
                        ---@type GoodNodeMB
                        local goodItemNodeEnv = goodItemNodeMB.Env
                        goodItemNodeEnv:Reload({
                            goodsId = v.goodsId, isShowNo = true, text = 'x' .. FormatCurrencyNum(v.goodsNum)
                        })
                        goodItemNodeEnv:SetClickButtonAction(function(goodsId)
                            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                            if isTable(vo) then
                                GameUtils.ShowCommonTipsBoard(go, vo.name, vo.desc, vo.quality, vo.id)
                            end
                        end)
                    end
                end
            end
        end
    else
        ---如果是起始区
        if not executeAnimation then
            trailBattleMgr:ScrollToAngle(0, true, isRight)
        end
    end
end

