function TrailStageHome:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self._loader) then
            self._loader:Release(true)
            self._loader = nil
        end
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.TrailQuestTask)
        if self.handler then
            Events.RemoveListener(Constants.EventNames.SCROLL_CHANGE, self.handler)
            self.handler = nil
        end

        if not isNull(self._timer) then
            ---删除计时器
            CDTimerModule.GetInstance():RemoveCD(self._timer)
            self._timer = nil
        end
        
        trailBattleMgr:Delete()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return TrailStageHome